:root { --bg: #f5f6f8; --surface: #ffffff; --border: #e3e6eb; --text: #1c2230; --muted: #6b7385; --accent: #3b5bdb; --accent-soft: #e7ecff; --danger: #c92a2a; --ok: #2b8a3e; --radius: 10px; font-family: Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; color: var(--text); background: var(--bg); }* { box-sizing: border-box; }body { margin: 0px; }a { color: var(--accent); text-decoration: none; }h1 { font-size: 24px; margin: 0px 0px 4px; }h2 { font-size: 17px; margin: 0px 0px 4px; }h3 { font-size: 13px; text-transform: uppercase; letter-spacing: 0.04em; color: var(--muted); margin: 0px 0px 10px; }p { margin: 4px 0px; }.muted { color: var(--muted); }.small { font-size: 12px; }.shell { display: grid; grid-template-columns: 232px 1fr; min-height: 100vh; }.sidebar { background: rgb(17, 24, 39); color: rgb(229, 231, 235); padding: 20px 14px; display: flex; flex-direction: column; gap: 24px; }.brand { font-weight: 700; font-size: 16px; padding: 0px 8px; }.logo { color: rgb(145, 167, 255); }.sidebar nav { display: flex; flex-direction: column; gap: 2px; flex: 1 1 0%; }.sidebar nav a { color: rgb(203, 210, 221); padding: 9px 10px; border-radius: 8px; font-size: 14px; }.sidebar nav a:hover { background: rgb(31, 41, 55); }.sidebar nav a.active { background: rgb(39, 52, 73); color: rgb(255, 255, 255); }.user-badge { display: flex; gap: 10px; align-items: center; padding: 8px; font-size: 13px; }.user-badge small { display: block; color: rgb(154, 164, 178); }.avatar { width: 34px; height: 34px; border-radius: 50%; background: rgb(59, 91, 219); display: grid; place-items: center; font-weight: 600; color: rgb(255, 255, 255); }.content { padding: 32px 40px; max-width: 1100px; width: 100%; }.page-header { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 24px; gap: 16px; }.card-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(230px, 1fr)); gap: 16px; }.card { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); padding: 18px; display: flex; flex-direction: column; gap: 6px; }.card.wide { grid-column: 1 / -1; }.big { font-size: 26px; font-weight: 700; }.meter { height: 6px; border-radius: 3px; background: rgb(237, 240, 244); overflow: hidden; margin: 6px 0px; }.meter-fill { height: 100%; background: var(--accent); }.sparkline { width: 100%; height: 34px; color: var(--accent); }.badge { padding: 2px 8px; border-radius: 10px; font-size: 12px; font-weight: 600; }.badge.ok { background: rgb(211, 249, 216); color: var(--ok); }.badge.warn { background: rgb(255, 243, 191); color: rgb(148, 98, 0); }.activity { list-style: none; padding: 0px; margin: 0px; }.activity li { display: flex; justify-content: space-between; padding: 8px 0px; border-bottom: 1px solid var(--border); font-size: 14px; }.activity li:last-child { border-bottom: 0px; }.skeleton-block { background: linear-gradient(90deg, rgb(236, 239, 243) 25%, rgb(246, 247, 249) 50%, rgb(236, 239, 243) 75%) 0% 0% / 200% 100%; animation: 1.2s ease 0s infinite normal none running shimmer; border-radius: 6px; }.page-skeleton { display: flex; flex-direction: column; gap: 16px; }.card-skeleton { gap: 10px; min-height: 170px; }@keyframes shimmer { 
  0% { background-position: 200% 0px; }
  100% { background-position: -200% 0px; }
}.panel { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); padding: 22px; margin-bottom: 20px; }.panel.empty { text-align: center; color: var(--muted); }.panel-head { margin-bottom: 16px; }.panel-actions { display: flex; justify-content: flex-end; gap: 10px; margin-top: 18px; padding-top: 16px; border-top: 1px solid var(--border); }.form-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 14px 18px; }.field { display: flex; flex-direction: column; gap: 6px; font-size: 13px; font-weight: 500; }.field.full { grid-column: 1 / -1; }input, textarea, select { font-style: inherit; font-variant: inherit; font-weight: inherit; font-stretch: inherit; line-height: inherit; font-family: inherit; font-size: 14px; padding: 9px 11px; border: 1px solid rgb(204, 210, 219); border-radius: 8px; background: rgb(255, 255, 255); color: var(--text); }input:focus, textarea:focus, select:focus { outline: 2px solid var(--accent-soft); border-color: var(--accent); }.button { display: inline-block; font-style: inherit; font-variant: inherit; font-stretch: inherit; line-height: inherit; font-family: inherit; font-size: 14px; font-weight: 600; padding: 9px 16px; border-radius: 8px; border: 1px solid var(--accent); background: var(--accent); color: rgb(255, 255, 255); cursor: pointer; }.button:disabled { opacity: 0.5; cursor: default; }.button.secondary { background: rgb(255, 255, 255); color: var(--text); border-color: rgb(204, 210, 219); }.button.danger { color: var(--danger); }.toggle-list { list-style: none; padding: 0px; margin: 0px; }.toggle-list li { display: flex; justify-content: space-between; align-items: center; padding: 12px 0px; border-bottom: 1px solid var(--border); }.switch { position: relative; width: 40px; height: 22px; }.switch input { opacity: 0; width: 0px; height: 0px; }.slider { position: absolute; inset: 0px; background: rgb(204, 210, 219); border-radius: 22px; cursor: pointer; transition: all 0.15s ease 0s; }.slider::before { content: ""; position: absolute; width: 16px; height: 16px; left: 3px; top: 3px; background: rgb(255, 255, 255); border-radius: 50%; transition: all 0.15s ease 0s; }.switch input:checked + .slider { background: var(--accent); }.switch input:checked + .slider::before { transform: translateX(18px); }.note-list { list-style: none; padding: 0px; margin: 0px; display: grid; gap: 10px; }.note-item { display: block; background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); padding: 14px 18px; color: var(--text); }.note-item:hover { border-color: var(--accent); }.note-title { font-weight: 600; margin-bottom: 4px; }.note-excerpt { font-size: 14px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }.editor { display: flex; flex-direction: column; gap: 12px; }.editor-toolbar { display: flex; align-items: center; gap: 16px; }.editor-toolbar .back { margin-right: auto; }.save-status { font-size: 13px; color: var(--muted); }.save-status.unsaved { color: rgb(148, 98, 0); }.save-status.error { color: var(--danger); }.editor-title { font-size: 22px; font-weight: 700; border: 0px; padding: 6px 0px; background: transparent; }.editor-title:focus { outline: none; }.editor-body { min-height: 360px; resize: vertical; line-height: 1.6; }.toasts { position: fixed; bottom: 24px; right: 24px; display: flex; flex-direction: column; gap: 8px; z-index: 10; }.toast { padding: 11px 16px; border-radius: 8px; font-size: 14px; color: rgb(255, 255, 255); box-shadow: rgba(0, 0, 0, 0.15) 0px 6px 20px; }.toast-success { background: rgb(43, 138, 62); }.toast-error { background: var(--danger); }

